import { SegmentedControl } from '@kerfjs/ui/segmented-control';
import { Toolbar } from '@kerfjs/ui/toolbar';
import '@kerfjs/ui/layout.css';

export type WorkspaceView = 'board' | 'list' | 'timeline';
export type WorkspaceAction = { type: 'workspace.view.set'; value: WorkspaceView };
const options = [
  { value: 'board', label: 'Board' },
  { value: 'list', label: 'List' },
  { value: 'timeline', label: 'Timeline' },
];
export function WorkspaceViewChoice({ value, dispatch }: {
  value: WorkspaceView;
  dispatch: (action: WorkspaceAction) => void;
}) {
  return <div className="kui-layout">
    <Toolbar>
      <SegmentedControl aria-label="Workspace view" options={options} value={value}
        onChange={(next: string) => {
          if ((next === 'board' || next === 'list' || next === 'timeline') && next !== value)
            dispatch({ type: 'workspace.view.set', value: next });
        }} />
    </Toolbar>
  </div>;
}
// Use the primitive's exclusive-selection and keyboard behavior; these choices
// change application presentation, so they are not tabpanel navigation.
// The supplied context does not include declarations: confirm options/onChange
// names against the installed public API before integration.
